package org.slavicmyths.client;
import java.util.*;
import com.mojang.blaze3d.vertex.PoseStack;
import net.minecraft.client.Minecraft;
import net.minecraft.client.renderer.*;
import net.minecraft.world.entity.*;
import net.minecraft.core.*;
import net.minecraft.nbt.*;
import net.minecraft.world.phys.Vec3;
import net.neoforged.api.distmarker.Dist;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import org.slavicmyths.quest185.*;
import org.slavicmyths.registry.ModEntities;
@EventBusSubscriber(modid="slavicmyths",value=Dist.CLIENT)
public final class Quest185Client {
 private static final Map<Integer,Long> TARGETS=new HashMap<>();private static int landSeconds;private static long landUntil;private static int bossId=-1;private static long weakUntil;private static final List<LivingEntity> ACTORS=new ArrayList<>();private static CompoundTag scene=new CompoundTag();private static String sceneKey="";private static long sceneAt,lastParticleTick=-1;private static int lastPage=-1;
 public static boolean outlined(Entity e){var mc=Minecraft.getInstance();return mc.player!=null&&mc.player.hasEffect(Quest185Content.TRACKER_EFFECT)&&mc.level!=null&&mc.level.getGameTime()<TARGETS.getOrDefault(e.getId(),0L);}
 public static void clearActors(){ACTORS.clear();sceneKey="";scene=new CompoundTag();lastPage=-1;}
 @SubscribeEvent public static void receive(Quest185Network.Received e){var mc=Minecraft.getInstance();var n=e.payload.data();String kind=n.getString("Kind");if(kind.equals("land_ward")){if(mc.level!=null){landSeconds=n.getInt("Seconds");landUntil=mc.level.getGameTime()+25;var at=BlockPos.of(n.getLong("Pos"));mc.level.addParticle(Quest185Content.LAND_WARD.get(),at.getX()+.5,at.getY()+1.05,at.getZ()+.5,0,.01,0);}return;}if(kind.equals("tracker")){TARGETS.clear();if(mc.level!=null)for(var row:n.getList("Targets",10))TARGETS.put(((CompoundTag)row).getInt("Entity"),mc.level.getGameTime()+15);return;}if(kind.equals("weakpoints")){bossId=n.getInt("Boss");weakUntil=n.getLong("Until");return;}if(kind.equals("closed")){clearActors();if(mc.screen instanceof Quest185Screen)mc.setScreen(null);return;}scene=n.copy();prepareActors();if(mc.screen instanceof Quest185Screen screen)screen.update(n);else mc.setScreen(new Quest185Screen(n));}
 private static void prepareActors(){var mc=Minecraft.getInstance();if(mc.level==null)return;String kind=scene.getString("Kind");if(!List.of("intro","ritual","warning","eye","earth_reward").contains(kind)||!scene.contains("Door")){clearActors();return;}String key=scene.getUUID("Token")+":"+kind+":"+scene.getInt("Mask");if(key.equals(sceneKey)){if(lastPage!=scene.getInt("Page")){lastPage=scene.getInt("Page");for(var actor:ACTORS){if(scene.getString("Speaker").equals("yaga")&&actor instanceof org.slavicmyths.yaga.BabaYaga y)y.sceneGesture(kind.equals("warning")?3:(kind.equals("ritual")||kind.equals("eye"))?4:2);else if(scene.getString("Speaker").equals("bayun")&&actor instanceof org.slavicmyths.bayun.BayunEntity c)c.begin("turn_attention");else if(scene.getString("Speaker").equals("wolf")&&actor instanceof org.slavicmyths.wolf.GreyWolf wolf)wolf.scenePose(org.slavicmyths.wolf.WolfTimeline.Move.HOWL_SUMMON);}}return;}ACTORS.clear();sceneKey=key;lastPage=scene.getInt("Page");sceneAt=mc.level.getGameTime();var door=BlockPos.of(scene.getLong("Door"));int mask=scene.getInt("Mask");var y=ModEntities.BABA_YAGA.get().create(mc.level);if(y!=null){y.setPos(door.getX()+.5,door.getY(),door.getZ()-1.5);y.sceneGesture(kind.equals("warning")?3:(kind.equals("ritual")||kind.equals("eye"))?4:1);ACTORS.add(y);}if((mask&2)!=0){var c=org.slavicmyths.bayun.BayunContent.ENTITY.get().create(mc.level);if(c!=null){c.setPos(door.getX()-1.3,door.getY(),door.getZ()-1.8);c.begin(scene.getString("Speaker").equals("bayun")?"turn_attention":"idle_sit");ACTORS.add(c);}}if((mask&4)!=0){var wolf=ModEntities.GREY_WOLF.get().create(mc.level);if(wolf!=null){wolf.setPos(door.getX()+2.7,door.getY(),door.getZ()-2.2);wolf.scenePose(scene.getString("Speaker").equals("wolf")?org.slavicmyths.wolf.WolfTimeline.Move.HOWL_SUMMON:org.slavicmyths.wolf.WolfTimeline.Move.NONE);ACTORS.add(wolf);}}for(var actor:ACTORS){actor.setNoGravity(true);actor.noPhysics=true;actor.setYRot(180);actor.yRotO=180;actor.yBodyRot=actor.yBodyRotO=actor.yHeadRot=actor.yHeadRotO=180;actor.xo=actor.getX();actor.yo=actor.getY();actor.zo=actor.getZ();}}
 @SubscribeEvent public static void render(net.neoforged.neoforge.client.event.RenderLevelStageEvent e){if(e.getStage()!=net.neoforged.neoforge.client.event.RenderLevelStageEvent.Stage.AFTER_ENTITIES)return;var mc=Minecraft.getInstance();if(mc.level==null||mc.player==null){clearActors();TARGETS.clear();return;}var camera=e.getCamera().getPosition();var buffers=mc.renderBuffers().bufferSource();for(var actor:ACTORS){actor.tickCount=(int)(mc.level.getGameTime()-sceneAt);if(actor.level()!=mc.level){clearActors();break;}if(actor.distanceToSqr(mc.player)>1024)continue;int light=LevelRenderer.getLightColor(mc.level,actor.blockPosition());String role=actor instanceof org.slavicmyths.yaga.BabaYaga?"yaga":actor instanceof org.slavicmyths.bayun.BayunEntity?"bayun":"wolf";if(!role.equals(scene.getString("Speaker")))light=LightTexture.pack(LightTexture.block(light)*3/4,LightTexture.sky(light)*3/4);mc.getEntityRenderDispatcher().render(actor,actor.getX()-camera.x,actor.getY()-camera.y,actor.getZ()-camera.z,180,e.getPartialTick().getGameTimeDeltaPartialTick(false),e.getPoseStack(),buffers,light);}
  if(mc.screen instanceof Quest185Screen&&(scene.getString("Kind").equals("ritual")||scene.getString("Kind").equals("eye"))&&scene.contains("Door")){var d=BlockPos.of(scene.getLong("Door"));if(mc.level.getGameTime()%4==0&&lastParticleTick!=mc.level.getGameTime()){lastParticleTick=mc.level.getGameTime();long age=mc.level.getGameTime()-sceneAt;boolean ring=scene.getInt("Ritual")==1&&age>=10&&age<36;for(int i=0;i<(ring?4:3);i++){double angle=age*.18+i*Math.PI/2;var at=new Vec3(d.getX()+.5+(ring?Math.cos(angle)*.3:(i-1)*.18),d.getY()+1.35+(ring?Math.sin(angle)*.3:Math.sin(age*.18+i)*.06),d.getZ()-1.8);var dust=new net.minecraft.core.particles.DustParticleOptions(new org.joml.Vector3f(.7f,.12f,.17f),.4f);mc.level.addParticle(Quest185Content.INSPECTION.get(),at.x,at.y,at.z,0,.01,0);}}}
  if((scene.getString("Kind").equals("eye")||scene.getString("Kind").equals("ritual")&&scene.getInt("Ritual")==2)&&scene.contains("Door")){var at=BlockPos.of(scene.getLong("Door"));for(int i=0;i<(scene.getString("Kind").equals("eye")?1:2);i++){var pose=e.getPoseStack();pose.pushPose();pose.translate(at.getX()+.5+(i==0?-.22:.22)-camera.x,at.getY()+1.45-camera.y,at.getZ()-1.85-camera.z);pose.scale(.32f,.32f,.32f);mc.getItemRenderer().renderStatic(new net.minecraft.world.item.ItemStack(i==0?org.slavicmyths.poloz.PolozContent.EYE.get():org.slavicmyths.poloz.PolozContent.HEART.get()),net.minecraft.world.item.ItemDisplayContext.GROUND,0xF000F0,net.minecraft.client.renderer.texture.OverlayTexture.NO_OVERLAY,pose,buffers,mc.level,0);pose.popPose();}}
  if(scene.getString("Kind").equals("eye")&&scene.getInt("Page")>0&&scene.contains("Door")){var at=BlockPos.of(scene.getLong("Door"));var pose=e.getPoseStack();pose.pushPose();pose.translate(at.getX()+.32-camera.x,at.getY()+1.3-camera.y,at.getZ()-1.9-camera.z);pose.scale(.35f,.35f,.35f);var sample=mc.level.getGameTime()-sceneAt<45?org.slavicmyths.mor.MorBlocks.BLOCKS.get("stone").get().defaultBlockState():net.minecraft.world.level.block.Blocks.STONE.defaultBlockState();mc.getBlockRenderer().renderSingleBlock(sample,pose,buffers,0xF000F0,net.minecraft.client.renderer.texture.OverlayTexture.NO_OVERLAY);pose.popPose();}
  if(mc.level.getGameTime()<weakUntil&&mc.level.getEntity(bossId) instanceof org.slavicmyths.poloz.GreatPoloz boss){var lines=buffers.getBuffer(RenderType.lines());for(var part:boss.parts){if(org.slavicmyths.poloz.PolozRules.multiplier(boss.phase(),part.segment,part.scar)<=0)continue;var box=part.getBoundingBox().move(-camera.x,-camera.y,-camera.z);LevelRenderer.renderLineBox(e.getPoseStack(),lines,box,1,.75f,.24f,1);}if(boss.phase()==1)LevelRenderer.renderLineBox(e.getPoseStack(),lines,boss.getBoundingBox().move(-camera.x,-camera.y,-camera.z),1,.75f,.24f,1);}
 }
 @SubscribeEvent public static void hud(net.neoforged.neoforge.client.event.RenderGuiEvent.Post e){var mc=Minecraft.getInstance();if(mc.player==null)return;if(mc.level!=null&&mc.level.getGameTime()<landUntil)e.getGuiGraphics().drawCenteredString(mc.font,Quest185Story.text("land_protected",landSeconds),e.getGuiGraphics().guiWidth()/2,e.getGuiGraphics().guiHeight()-58,0xB3D8A0);var ward=mc.player.getEffect(Quest185Content.WARD_EFFECT);if(ward!=null){int seconds=(ward.getDuration()+19)/20;e.getGuiGraphics().drawString(mc.font,String.format(java.util.Locale.ROOT,"%02d:%02d",seconds/60,seconds%60),e.getGuiGraphics().guiWidth()-39,29,0xD8C5A1,true);}}
 @EventBusSubscriber(modid="slavicmyths",value=Dist.CLIENT,bus=EventBusSubscriber.Bus.MOD)
 public static final class Registration {
  @SubscribeEvent public static void particles(net.neoforged.neoforge.client.event.RegisterParticleProvidersEvent e){e.registerSpriteSet(Quest185Content.PURIFY.get(),s->new Quest185Particle.Provider(s,false));e.registerSpriteSet(Quest185Content.GREEN.get(),s->new Quest185Particle.Provider(s,false));e.registerSpriteSet(Quest185Content.LAND_WARD.get(),s->new Quest185Particle.Provider(s,false));e.registerSpriteSet(Quest185Content.INSPECTION.get(),s->new Quest185Particle.Provider(s,true));}
  @SubscribeEvent public static void models(net.neoforged.neoforge.client.event.ModelEvent.RegisterAdditional e){for(String name:List.of("wolf_call","mor_ward","tracker_sense","cleansing_powder"))for(String suffix:List.of("_icon","_held"))e.register(net.minecraft.client.resources.model.ModelResourceLocation.standalone(Quest185Content.id("item/"+name+suffix)));}
  @SubscribeEvent public static void extensions(net.neoforged.neoforge.client.extensions.common.RegisterClientExtensionsEvent e){var renderer=new Quest185ItemRenderer();e.registerItem(new net.neoforged.neoforge.client.extensions.common.IClientItemExtensions(){@Override public net.minecraft.client.renderer.BlockEntityWithoutLevelRenderer getCustomRenderer(){return renderer;}},Quest185Content.CALL.get(),Quest185Content.WARD.get(),Quest185Content.TRACKER.get(),Quest185Content.POWDER.get());}
  @SuppressWarnings("unchecked") @SubscribeEvent public static void renderers(net.neoforged.neoforge.client.event.EntityRenderersEvent.RegisterRenderers e){e.registerEntityRenderer(Quest185Content.WOLF.get(),c->(net.minecraft.client.renderer.entity.EntityRenderer<WolfSupport>)(Object)new GreyWolfRenderer(c));}
 }
 @SubscribeEvent public static void logout(net.neoforged.neoforge.client.event.ClientPlayerNetworkEvent.LoggingOut e){clearActors();TARGETS.clear();weakUntil=0;bossId=-1;landUntil=0;landSeconds=0;}
 private Quest185Client(){}
}
